#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys

import booster_robotics_sdk_python as br


CAMERA_MODE_MAP = {
    "normal": br.CameraSetMode.kCameraModeNormal,
    "high": br.CameraSetMode.kCameraModeHighResolution,
    "normal_enable": br.CameraSetMode.kCameraModeNormalEnable,
    "high_enable": br.CameraSetMode.kCameraModeHighResolutionEnable,
}

CAMERA_STATUS_NAME = {
    br.CameraControlStatus.kCameraStatusNormal: "normal",
    br.CameraControlStatus.kCameraStatusHighResolution: "high_resolution",
    br.CameraControlStatus.kCameraStatusError: "error",
    br.CameraControlStatus.kCameraStatusNull: "null",
}


def print_help():
    print(
        """
Available commands (X5 camera):
  help                              - Show this help
  set_mode <normal|high|normal_enable|high_enable>
                                    - Change camera mode via X5CameraClient.ChangeMode()
  get_status                        - Query current camera status via X5CameraClient.GetStatus()
  raw_set_mode <mode>               - Send X5CameraChangeModeParameter via SendApiRequest()
  raw_get_status                    - Query status via SendApiRequestWithResponse()
  quit / exit                       - Exit
"""
    )


def parse_camera_mode(token: str):
    mode = CAMERA_MODE_MAP.get(token.lower())
    if mode is None:
        raise ValueError(
            "camera mode must be one of: normal, high, normal_enable, high_enable"
        )
    return mode


def camera_status_to_str(status) -> str:
    return CAMERA_STATUS_NAME.get(status, str(status))


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} networkInterface")
        print(f"Example: {sys.argv[0]} eno1")
        sys.exit(-1)

    net_if = sys.argv[1]

    print(f"Initializing ChannelFactory on {net_if}...")
    br.ChannelFactory.Instance().Init(0, net_if)

    client = br.X5CameraClient()
    print("Initializing X5CameraClient...")
    client.Init()

    print("X5 Camera CLI started.")
    print_help()

    while True:
        try:
            line = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nExit.")
            break

        if not line:
            continue

        parts = line.split()
        cmd = parts[0]
        args = parts[1:]

        try:
            if cmd in ("help", "?"):
                print_help()

            elif cmd == "set_mode":
                if len(args) != 1:
                    print("Usage: set_mode <normal|high|normal_enable|high_enable>")
                    continue

                mode = parse_camera_mode(args[0])
                client.ChangeMode(mode)
                print(f"[OK] ChangeMode sent: {args[0]}")

            elif cmd == "get_status":
                status = client.GetStatus()
                print(
                    "[OK] camera status:",
                    camera_status_to_str(status.status),
                    f"({status.status})",
                )

            elif cmd == "raw_set_mode":
                if len(args) != 1:
                    print("Usage: raw_set_mode <normal|high|normal_enable|high_enable>")
                    continue

                param = br.X5CameraChangeModeParameter(parse_camera_mode(args[0]))
                client.SendApiRequest(br.X5CameraApiId.kChangeMode, param.to_json_str())
                print(f"[OK] raw ChangeMode sent: {args[0]}")

            elif cmd == "raw_get_status":
                resp = client.SendApiRequestWithResponse(
                    br.X5CameraApiId.kGetStatus, ""
                )
                print("[OK] SendApiRequestWithResponse returned:", resp)

            elif cmd in ("quit", "exit"):
                print("Bye.")
                break

            else:
                print(f"Unknown command: {cmd}")
                print("Type 'help' to show available commands.")

        except Exception as e:
            print(f"[ERROR] Request failed: {e}")


if __name__ == "__main__":
    main()
